def api_objects(chart: Chart) -> list[ApiObject]:
    """Every ApiObject under `chart`; `Chart.api_objects` holds direct children only."""
    return [cast(ApiObject, node) for node in chart.node.find_all() if ApiObject.is_api_object(node)]


@dataclass(frozen=True)
class RenderedDirectory:
    """A directory `generation.write_directory` wrote, as its Flux Kustomization reads it."""

    artifact: ArtifactGeneratorSpecArtifacts
    decryption: KustomizationSpecDecryption | None  # set exactly when a sibling is SOPS ciphertext
    objects: tuple[ObjectId, ...]
    chart_kinds: frozenset[str]  # custom-resource kinds a HelmRelease here renders; `objects` cannot show them

    @property
    def kinds(self) -> frozenset[str]:
        return frozenset(obj.kind for obj in self.objects) | self.chart_kinds

    @property
    def stateful(self) -> bool:
        return any((obj.group, obj.kind) in STATEFUL_KINDS for obj in self.objects)

    def health_checks(self, *kinds: str) -> list[KustomizationSpecHealthChecks]:
        """For an admission target only (#7094 rule 4); replaces `flux.health_checks(chart, kinds)`."""
        return [
            KustomizationSpecHealthChecks(api_version=obj.api_version, kind=obj.kind, name=obj.name, namespace=obj.namespace)
            for obj in sorted((obj for obj in self.objects if obj.kind in kinds), key=lambda obj: kinds.index(obj.kind))
        ]


# (dependent, target) -> one-line reason. #7094 rule 2 admits two kinds of reason: the bootstrap never
# converges without the edge, or applying out of order destroys something. "It needs the secret, the
# namespace or the database" converges by retry and is not a reason. An edge orders the bootstrap only.
ORDERING_EXCEPTIONS: Mapping[tuple[str, str], str] = MappingProxyType({})


def flux_kustomization(
    chart: Chart,
    name: str,
    source: RenderedDirectory | ArtifactGeneratorSpecArtifacts | KustomizationSpecSourceRef,
    *,
    path: str | None = None,
    wait: bool | None = None,  # Flux's default, off; an admission target passes True (#7094 rule 4)
    deletion_policy: KustomizationSpecDeletionPolicy | None = None,  # None: derived for a RenderedDirectory
    decryption: KustomizationSpecDecryption | None = None,
    # ... the other KustomizationSpec keywords, unchanged
) -> Kustomization:
    if isinstance(source, RenderedDirectory):
        if decryption is not None:
            raise ValueError(f"{name=}: a rendered directory derives its decryption; got {decryption=}")
        decryption = source.decryption
        if deletion_policy is None and source.stateful:
            deletion_policy = KustomizationSpecDeletionPolicy.ORPHAN  # a disposable cache passes MIRROR_PRUNE
        source = source.artifact
    match source:  # as today: an artifact derives sourceRef and path, and raises on an explicit path=
        ...


@jsii.implements(IValidation)  # a plain class: jsii sets __jsii_ref__, which a frozen dataclass refuses
class AdmissionGraph:
    """#7094 on the kustomizations chart, checked against what each node's directory renders."""

    def __init__(self, chart: Chart, directories: Sequence[RenderedDirectory]) -> None:
        self._chart = chart
        self._kinds = {directory.artifact.name: directory.kinds for directory in directories}  # by sourceRef name

    def validate(self) -> list[str]:
        nodes = [obj.to_json() for obj in api_objects(self._chart) if obj.kind == "Kustomization"]
        return [
            # (a) each rendered custom-resource kind reaches its provider in crd_layering.OPERATOR_CRDS
            *unreached_providers(nodes, self._kinds),
            # (b) each edge targets a CRD provider, a Fail-webhook operator or a postBuild source of the
            #     dependent, or is listed in ORDERING_EXCEPTIONS
            *unjustified_edges(nodes, self._kinds),
            # (c) wait, healthChecks and healthCheckExprs only on a node such an edge targets; each one gates
            *misplaced_gates(nodes, self._kinds),
        ]


# generation.py: write_charts attaches FleetRules (C6) and returns the charts it built
def write_directory(
    root: Path,
    artifact: ArtifactGeneratorSpecArtifacts,
    *chart_builders: Callable[[App], Chart],
    siblings: Sequence[str] = (),
    namespace: str | None = None,
    components: Sequence[str] = (),
    config_map_generator: Sequence[ConfigMapArgs] = (),
    chart_kinds: Sequence[str] = (),
    fleet: FleetExceptions = FleetExceptions(),
) -> RenderedDirectory:
    """One component's directory (#7094 rule 3)."""
    directory = artifact_directory(artifact)
    if len(artifact.copy) != 1:
        raise ValueError(f"{artifact.name=}: the writer lists one directory; this artifact also copies shared bases")
    charts = write_charts(root, directory, *chart_builders, fleet=fleet)
    write_yaml(
        root / directory / "kustomization.yaml",
        kustomize_kustomization(
            resources=[*(f"{Names.to_dns_label(chart)}.k8s.yaml" for chart in charts), *siblings],
            namespace=namespace,
            components=components,
